from typing import List
from collections import Counter


class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        count = Counter(nums)
        best = None
        for x in count:
            rest = total - x
            if rest % 2 != 0:
                continue
            target = rest // 2
            if target not in count:
                continue
            if target == x and count[x] < 2:
                continue
            if best is None or x > best:
                best = x
        return best

